    return (
      <NavLink
        to={route.path}
        key={index}
        className={({ isActive }) =>
          `${styles.mobileNavLink} ${isActive ? styles.activeLink : ""}`
        }
      >
        <div className={styles.iconWrapper}>{route.icon}</div>
